import React, { useCallback, useEffect, useRef, useState } from "react";
import { Helmet } from "react-helmet";
import { Link as RouterLink, useNavigate, useParams } from "react-router-dom";
import { Check, ChevronLeft, ChevronRight, Heart, MapPin, Users, X } from "lucide-react";
import SiteChrome from "@/components/SiteChrome";
import { Skeleton } from "@/components/ui/skeleton";
import { apiFetch } from "@/lib/api";
import { mediaRenderDebug, resolveMediaUrl, selectMediaUrl, venueMediaUrl } from "@/lib/media";
import MapLocation from "@/components/MapLocation";
import GoogleLocationPicker from "@/components/GoogleLocationPicker";

const taxonomyCacheKey = "ykcircle-venue-taxonomy-v1";
const Link = RouterLink;
const asList = (data, key) => Array.isArray(data) ? data : data?.[key] || [];
const venueId = (venue) => venue?.id ?? venue?.venueId ?? venue?.venue_id ?? venue?.venue?.id;
const normalizeVenue = (venue) => ({ ...venue, id: venueId(venue) });
const authHeaders = () => ({ Authorization: `Bearer ${localStorage.getItem("authToken")}` });
const inputClass = "mt-2 min-h-11 w-full border border-border bg-background px-3";
const textareaClass = "mt-2 min-h-28 w-full border border-border bg-background p-3";

const getError = (data, fallback) => data?.error || data?.message || fallback;
const humanize = (value = "") => String(value).replace(/[-_]/g, " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
const toNumber = (value) => value === "" || value == null ? undefined : Number(value);
const publicLocation = (venue) => {
  const location = venue.location || {};
  if (["private", "private_until_booking"].includes(venue.locationVisibility)) return "Exact address shared after booking confirmation.";
  const area = [location.locality || venue.city, location.municipality || venue.municipality, location.region || venue.region, location.country || venue.country].filter(Boolean);
  if (venue.locationVisibility === "exact") return [venue.addressLine1 || venue.address, ...area].filter(Boolean).join(", ");
  return area.join(", ") || "Location shared on request";
};
const priceLabel = (venue) => {
  const pricing = venue.pricing || {};
  if ((pricing.unit || venue.priceUnit) === "contact") return "Contact venue for pricing";
  const price = pricing.from ?? venue.priceFrom;
  if (price == null || price === "") return "Contact venue for pricing";
  return `From ${new Intl.NumberFormat("sv-SE", { maximumFractionDigits: 0 }).format(price)} ${pricing.currency || venue.currency || "SEK"}${pricing.unit || venue.priceUnit ? ` / ${humanize(pricing.unit || venue.priceUnit).toLowerCase()}` : ""}`;
};
const capacityLabel = (venue) => {
  const capacity = venue.capacity || {};
  const value = capacity.max ?? venue.capacityMax ?? capacity.standing ?? venue.standingCapacity;
  return value ? `Up to ${value} guests` : "Capacity on request";
};
// Venue image URLs are API-supplied and may carry a short-lived signed token.
// A bare filename is intentionally not a renderable media URL.
const imageUrl = venueMediaUrl;
const galleryImageUrl = (image) => resolveMediaUrl(selectMediaUrl(
  image?.url,
  image?.imageUrl,
  image?.image_url,
  image?.mediaUrl,
  image?.media_url,
  image?.filename,
));

async function loadTaxonomy() {
  try {
    const cached = sessionStorage.getItem(taxonomyCacheKey);
    if (cached) return JSON.parse(cached);
  } catch { /* An unavailable storage area should not block venue discovery. */ }
  const responses = await Promise.all([
    apiFetch("/api/venue-types"),
    apiFetch("/api/venue-event-types"),
    apiFetch("/api/venue-amenities"),
  ]);
  const data = await Promise.all(responses.map(async (response) => {
    const body = await response.json();
    if (!response.ok) throw new Error(getError(body, "Unable to load venue filters."));
    return body;
  }));
  const taxonomy = {
    venueTypes: asList(data[0], "venueTypes").length ? asList(data[0], "venueTypes") : asList(data[0], "types"),
    eventTypes: asList(data[1], "eventTypes").length ? asList(data[1], "eventTypes") : asList(data[1], "venueEventTypes"),
    amenities: asList(data[2], "amenities"),
  };
  try { sessionStorage.setItem(taxonomyCacheKey, JSON.stringify(taxonomy)); } catch { /* ignore */ }
  return taxonomy;
}

function useTaxonomy() {
  const [state, setState] = useState({ loading: true, error: "", value: { venueTypes: [], eventTypes: [], amenities: [] } });
  const load = useCallback(() => {
    setState((current) => ({ ...current, loading: true, error: "" }));
    loadTaxonomy().then((value) => setState({ loading: false, error: "", value })).catch((error) => setState((current) => ({ ...current, loading: false, error: error.message })));
  }, []);
  useEffect(() => { load(); }, [load]);
  return { ...state, reload: load };
}

function Shell({ title, description, children, noindex = false }) {
  return <SiteChrome><Helmet><title>{title} | YKCircle</title>{description && <meta name="description" content={description} />}{noindex && <meta name="robots" content="noindex" />}</Helmet><section className="mx-auto max-w-[76rem] px-5 pb-28 pt-32 sm:px-8 sm:pt-40">{children}</section></SiteChrome>;
}

function ErrorState({ error, retry }) {
  return <div role="alert" className="mt-8 border border-destructive/30 bg-destructive/5 p-5 text-sm text-destructive"><p>{error}</p>{retry && <button type="button" onClick={retry} className="mt-3 border border-destructive/40 px-3 py-2 text-foreground">Try again</button>}</div>;
}

function VenueCard({ venue, compact = false }) {
  const photo = imageUrl(venue);
  if (photo) mediaRenderDebug({ component: "VenueCard", venueId: venueId(venue), rawUrl: photo });
  const amenities = (venue.amenities || []).slice(0, 3);
  const destination = venue.slug || venueId(venue);
  return <article className="group relative overflow-hidden border border-border bg-background transition-colors hover:border-primary">
    <Link to={destination ? `/venues/slug/${destination}` : "/venues"} className="block">
      <div className="aspect-[16/9] bg-secondary/60">{photo ? <img src={photo} alt="" className="h-full w-full object-cover" /> : <div className="flex h-full items-end bg-[linear-gradient(135deg,hsl(var(--primary)/.16),hsl(var(--secondary)))] p-5 font-display text-2xl text-muted-foreground">Venue</div>}</div>
      <div className="p-5"><div className="flex items-start justify-between gap-3"><h2 className="font-display text-2xl font-semibold leading-tight">{venue.name}</h2>{venue.sponsored && <span className="shrink-0 border border-primary/50 px-2 py-1 text-[0.65rem] font-semibold uppercase tracking-wider text-primary">Sponsored</span>}</div>
        <p className="mt-2 flex items-center gap-1 text-sm text-muted-foreground"><MapPin className="h-4 w-4" />{publicLocation(venue)}</p>
        <p className="mt-3 text-sm font-medium">{venue.venueTypeName || humanize(venue.venueType || "Venue")}</p>
        <p className="mt-1 flex items-center gap-1 text-sm text-muted-foreground"><Users className="h-4 w-4" />{capacityLabel(venue)}</p>
        <p className="mt-4 font-medium text-primary">{priceLabel(venue)}</p>
        {!compact && amenities.length > 0 && <p className="mt-3 line-clamp-1 text-sm text-muted-foreground">{amenities.map((item) => item.name || humanize(item.slug || item)).join(" · ")}</p>}
      </div>
    </Link>
  </article>;
}

function VenueCardSkeleton() {
  return <div className="overflow-hidden border border-border p-5"><Skeleton className="-mx-5 -mt-5 h-48 rounded-none" /><Skeleton className="mt-5 h-7 w-2/3" /><Skeleton className="mt-3 h-4 w-1/2" /><Skeleton className="mt-6 h-5 w-1/3" /></div>;
}

function FilterSelect({ label, value, onChange, options, placeholder }) {
  return <label className="block text-sm font-medium">{label}<select value={value} onChange={(event) => onChange(event.target.value)} className={inputClass}><option value="">{placeholder}</option>{options.map((item) => <option key={item.slug || item.id || item} value={item.slug || item}>{item.name || humanize(item.slug || item)}</option>)}</select></label>;
}

export function VenuesDiscoveryPage({ city: routeCity = "", venueType: routeVenueType = "" }) {
  const taxonomy = useTaxonomy();
  const [filters, setFilters] = useState({ city: routeCity.replace(/-/g, " "), venueType: routeVenueType, eventType: "", amenity: "", minCapacity: "", maxCapacity: "", maxPrice: "", verified: false });
  const [state, setState] = useState({ loading: true, error: "", venues: [] });
  useEffect(() => setFilters((current) => ({ ...current, city: routeCity.replace(/-/g, " "), venueType: routeVenueType })), [routeCity, routeVenueType]);
  const load = useCallback(async () => {
    setState((current) => ({ ...current, loading: true, error: "" }));
    const params = new URLSearchParams();
    Object.entries(filters).forEach(([key, value]) => { if (value !== "" && value !== false) params.set(key, value === true ? "true" : value); });
    try {
      const response = await apiFetch(`/api/venues${params.size ? `?${params}` : ""}`);
      const data = await response.json();
      if (!response.ok) throw new Error(getError(data, "We couldn't load venues. Try again."));
      setState({ loading: false, error: "", venues: asList(data, "venues").map(normalizeVenue).filter((venue) => venue.id != null) });
    } catch (error) { setState((current) => ({ ...current, loading: false, error: error.message })); }
  }, [filters]);
  useEffect(() => { load(); }, [load]);
  const setFilter = (key) => (value) => setFilters((current) => ({ ...current, [key]: value }));
  const title = routeCity ? `Venues in ${humanize(routeCity)}` : "Find a venue for your next event";
  return <Shell title={title} description="Discover spaces for meetups, workshops, celebrations and community events."><div className="max-w-3xl"><p className="text-xs uppercase tracking-[0.28em] text-primary">Venue marketplace</p><h1 className="mt-3 font-display text-4xl font-bold sm:text-5xl">{title}</h1><p className="mt-4 text-muted-foreground">Find spaces that fit your people, plan and budget. Send a request—no payment or booking is completed here.</p></div>
    <form onSubmit={(event) => { event.preventDefault(); load(); }} className="mt-9 grid gap-3 border border-border bg-secondary/20 p-4 sm:grid-cols-2 lg:grid-cols-4">
      <label className="block text-sm font-medium">Location<input value={filters.city} onChange={(event) => setFilter("city")(event.target.value)} placeholder="City or area" className={inputClass} /></label>
      <FilterSelect label="Venue type" value={filters.venueType} onChange={setFilter("venueType")} options={taxonomy.value.venueTypes} placeholder="Any type" />
      <FilterSelect label="Suitable for" value={filters.eventType} onChange={setFilter("eventType")} options={taxonomy.value.eventTypes} placeholder="Any event" />
      <FilterSelect label="Amenity" value={filters.amenity} onChange={setFilter("amenity")} options={taxonomy.value.amenities} placeholder="Any amenity" />
      <label className="block text-sm font-medium">Minimum guests<input type="number" min="1" value={filters.minCapacity} onChange={(event) => setFilter("minCapacity")(event.target.value)} className={inputClass} /></label>
      <label className="block text-sm font-medium">Maximum guests<input type="number" min="1" value={filters.maxCapacity} onChange={(event) => setFilter("maxCapacity")(event.target.value)} className={inputClass} /></label>
      <label className="block text-sm font-medium">Maximum price (SEK)<input type="number" min="0" value={filters.maxPrice} onChange={(event) => setFilter("maxPrice")(event.target.value)} className={inputClass} /></label>
      <label className="flex min-h-11 items-end gap-2 pb-1 text-sm font-medium"><input type="checkbox" checked={filters.verified} onChange={(event) => setFilter("verified")(event.target.checked)} /> Verified venues only</label>
      <div className="flex items-end"><button className="min-h-11 w-full bg-primary px-4 text-sm font-medium text-primary-foreground">Search venues</button></div>
      {taxonomy.error && <p className="sm:col-span-2 lg:col-span-4 text-sm text-muted-foreground">Filters are unavailable right now; you can still search by location.</p>}
    </form>
    {state.error ? <ErrorState error={state.error} retry={load} /> : state.loading ? <div className="mt-9 grid gap-5 md:grid-cols-2 lg:grid-cols-3">{[1, 2, 3, 4, 5, 6].map((item) => <VenueCardSkeleton key={item} />)}</div> : state.venues.length ? <div className="mt-9 grid gap-5 md:grid-cols-2 lg:grid-cols-3">{state.venues.map((venue) => <VenueCard key={venue.id} venue={venue} />)}</div> : <p className="mt-9 border border-border p-6 text-muted-foreground">No venues found for these filters.</p>}
  </Shell>;
}

function ImageLightbox({ images, index, onClose, onNavigate, onImageError }) {
  useEffect(() => {
    const handleKey = (event) => {
      if (event.key === "Escape") onClose();
      if (event.key === "ArrowRight") onNavigate((index + 1) % images.length);
      if (event.key === "ArrowLeft") onNavigate((index - 1 + images.length) % images.length);
    };
    window.addEventListener("keydown", handleKey);
    return () => window.removeEventListener("keydown", handleKey);
  }, [images.length, index, onClose, onNavigate]);
  const current = images[index];
  if (!current) return null;
  return <div role="dialog" aria-modal="true" aria-label="Venue photo" className="fixed inset-0 z-[80] flex items-center justify-center bg-black/90 p-4 sm:p-8" onClick={onClose}>
    <button type="button" onClick={onClose} aria-label="Close" className="absolute right-4 top-4 flex h-11 w-11 items-center justify-center border border-white/30 text-white"><X className="h-5 w-5" /></button>
    {images.length > 1 && <button type="button" onClick={(event) => { event.stopPropagation(); onNavigate((index - 1 + images.length) % images.length); }} aria-label="Previous photo" className="absolute left-2 top-1/2 flex h-11 w-11 -translate-y-1/2 items-center justify-center border border-white/30 text-white sm:left-4"><ChevronLeft className="h-6 w-6" /></button>}
    <img src={current.src} alt={current.caption || ""} className="max-h-full max-w-full object-contain" onClick={(event) => event.stopPropagation()} onError={onImageError} />
    {images.length > 1 && <button type="button" onClick={(event) => { event.stopPropagation(); onNavigate((index + 1) % images.length); }} aria-label="Next photo" className="absolute right-2 top-1/2 flex h-11 w-11 -translate-y-1/2 items-center justify-center border border-white/30 text-white sm:right-4"><ChevronRight className="h-6 w-6" /></button>}
    {current.caption && <p className="absolute bottom-6 left-1/2 max-w-lg -translate-x-1/2 px-3 text-center text-sm text-white/80">{current.caption}</p>}
    {images.length > 1 && <p className="absolute bottom-6 right-6 text-sm text-white/60">{index + 1} / {images.length}</p>}
  </div>;
}

function InquiryForm({ venue, onClose }) {
  const [form, setForm] = useState({ eventName: "", eventType: "", requestedDate: "", startTime: "", endTime: "", expectedGuests: "", budget: "", message: "" });
  const [state, setState] = useState({ saving: false, error: "", success: false });
  const update = (key) => (event) => setForm((current) => ({ ...current, [key]: event.target.value }));
  const submit = async (event) => { event.preventDefault(); setState({ saving: true, error: "", success: false }); try { const id = venueId(venue); if (id == null) throw new Error("This venue is missing its ID and cannot receive requests yet."); const payload = { ...form, expectedGuests: toNumber(form.expectedGuests), budget: toNumber(form.budget) }; const response = await apiFetch(`/api/venues/${id}/inquiries`, { method: "POST", headers: { ...authHeaders(), "Content-Type": "application/json" }, body: JSON.stringify(payload) }); const data = await response.json(); if (!response.ok) throw new Error(getError(data, "Unable to send your venue request.")); setState({ saving: false, error: "", success: true }); } catch (error) { setState({ saving: false, error: error.message, success: false }); } };
  if (state.success) return <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/50 px-5"><section role="dialog" aria-modal="true" className="w-full max-w-lg border border-border bg-background p-6 shadow-xl"><h2 className="font-display text-3xl">Request sent</h2><p className="mt-3 text-muted-foreground">{venue.name} has received your request. This is an inquiry, not a confirmed booking.</p><button type="button" onClick={onClose} className="mt-6 bg-primary px-5 py-3 text-sm text-primary-foreground">Done</button></section></div>;
  return <div className="fixed inset-0 z-[70] overflow-y-auto bg-black/50 px-5 py-8"><section role="dialog" aria-modal="true" aria-labelledby="inquiry-title" className="mx-auto max-w-2xl border border-border bg-background p-6 shadow-xl"><div className="flex justify-between gap-5"><div><p className="text-xs uppercase tracking-[0.22em] text-primary">Venue request</p><h2 id="inquiry-title" className="mt-2 font-display text-3xl">Request {venue.name}</h2></div><button type="button" onClick={onClose} className="h-10 border border-border px-3 text-sm">Close</button></div><p className="mt-3 text-sm text-muted-foreground">This sends an inquiry to the venue. It does not reserve the space or take payment.</p><form onSubmit={submit} className="mt-6 grid gap-4 sm:grid-cols-2"><label className="text-sm font-medium">Event name *<input required value={form.eventName} onChange={update("eventName")} className={inputClass} /></label><label className="text-sm font-medium">Event type<input value={form.eventType} onChange={update("eventType")} className={inputClass} /></label><label className="text-sm font-medium">Preferred date<input type="date" value={form.requestedDate} onChange={update("requestedDate")} className={inputClass} /></label><label className="text-sm font-medium">Expected guests<input type="number" min="1" value={form.expectedGuests} onChange={update("expectedGuests")} className={inputClass} /></label><label className="text-sm font-medium">Start time<input type="time" value={form.startTime} onChange={update("startTime")} className={inputClass} /></label><label className="text-sm font-medium">End time<input type="time" value={form.endTime} onChange={update("endTime")} className={inputClass} /></label><label className="text-sm font-medium">Budget (optional)<input type="number" min="0" value={form.budget} onChange={update("budget")} className={inputClass} /></label><label className="sm:col-span-2 text-sm font-medium">Message *<textarea required value={form.message} onChange={update("message")} className={textareaClass} /></label>{state.error && <p role="alert" className="sm:col-span-2 text-sm text-destructive">{state.error}</p>}<button disabled={state.saving} className="sm:col-span-2 justify-self-start bg-primary px-5 py-3 text-sm text-primary-foreground disabled:opacity-60">{state.saving ? "Sending…" : "Send venue request"}</button></form></section></div>;
}

export function VenueDetailPage({ legacyId = false, managed = false }) {
  const params = useParams(); const slug = legacyId ? params.id || params.city : params.slug; const navigate = useNavigate();
  const DetailLink = ({ to, ...props }) => <RouterLink to={to === "/venues" && managed ? "/profile/venues" : to} {...props} />;
  const [state, setState] = useState({ loading: true, error: "", venue: null, similar: [] }); const [inquiryOpen, setInquiryOpen] = useState(false); const [saved, setSaved] = useState(false); const [saveError, setSaveError] = useState(""); const [lightboxIndex, setLightboxIndex] = useState(null);
  const load = useCallback(async () => { setState((current) => ({ ...current, loading: true, error: "" })); try { const endpoint = legacyId ? `/api/venues/${slug}` : `/api/venues/slug/${encodeURIComponent(slug)}`; const response = await apiFetch(endpoint); const data = await response.json(); if (!response.ok) throw new Error(getError(data, "We couldn't load this venue. Try again.")); const venue = normalizeVenue(data.venue || data); const id = venueId(venue); setSaved(Boolean(venue.isSaved || venue.saved)); const related = id == null ? [] : await apiFetch(`/api/venues/${id}/similar`).then(async (result) => result.ok ? result.json() : []); setState({ loading: false, error: "", venue, similar: (asList(related, "venues").length ? asList(related, "venues") : asList(related, "similar")).map(normalizeVenue).filter((item) => item.id != null) }); } catch (error) { setState((current) => ({ ...current, loading: false, error: error.message })); } }, [legacyId, slug]);
  useEffect(() => { load(); }, [load]);
  const venue = state.venue;
  // A draft venue's image URL carries a short-lived signed token. If it expires
  // while this page is left open, one silent re-fetch picks up a fresh token
  // without flashing the full loading skeleton.
  const imageRetriedRef = useRef(false);
  const handleImageError = useCallback(async () => {
    if (imageRetriedRef.current) return;
    imageRetriedRef.current = true;
    try {
      const endpoint = legacyId ? `/api/venues/${slug}` : `/api/venues/slug/${encodeURIComponent(slug)}`;
      const response = await apiFetch(endpoint);
      const data = await response.json();
      if (response.ok) setState((current) => ({ ...current, venue: normalizeVenue(data.venue || data) }));
    } catch { /* Keep showing the previous venue if the silent refresh fails. */ }
  }, [legacyId, slug]);
  const toggleSaved = async () => { if (!localStorage.getItem("authToken")) return navigate(`/login?from=${encodeURIComponent(window.location.pathname)}`); setSaveError(""); try { const id = venueId(venue); if (id == null) throw new Error("This venue is missing its ID and cannot be saved yet."); const response = await apiFetch(`/api/venues/${id}/save`, { method: saved ? "DELETE" : "POST", headers: authHeaders() }); const data = await response.json(); if (!response.ok) throw new Error(getError(data, "Unable to update saved venues.")); setSaved((current) => !current); } catch (error) { setSaveError(error.message); } };
  // Availability is checked before sending an inquiry so organizers select a
  // backend-provided bookable interval instead of guessing from the listing.
  const request = () => { const id = venueId(venue); if (id != null) navigate(`/venues/${id}/availability`); };
  if (state.loading) return <Shell title="Venue"><div className="mx-auto max-w-5xl"><Skeleton className="h-96 w-full" /><Skeleton className="mt-8 h-12 w-1/2" /><Skeleton className="mt-4 h-6 w-1/3" /></div></Shell>;
  if (state.error || !venue) return <Shell title="Venue"><DetailLink to="/venues" className="text-sm text-primary underline">Back to {managed ? "manage venues" : "venues"}</DetailLink><ErrorState error={state.error || "Venue not found."} retry={load} /></Shell>;
  const photo = imageUrl(venue);
  const galleryImages = (venue.images || []).map((item) => {
    const src = galleryImageUrl(item);
    if (src) mediaRenderDebug({ component: "VenueDetailGallery", venueId: venueId(venue), rawUrl: src });
    return { src, caption: item.caption || "" };
  }).filter((entry) => entry.src);
  const heroInGallery = galleryImages.some((entry) => entry.src === photo);
  const lightboxImages = photo && !heroInGallery ? [{ src: photo, caption: "" }, ...galleryImages] : galleryImages;
  const galleryOffset = photo && !heroInGallery ? 1 : 0;
  const heroLightboxIndex = photo ? Math.max(lightboxImages.findIndex((entry) => entry.src === photo), 0) : null;
  const verified = venue.verificationStatus === "verified" || venue.isVerified;
  if (photo) mediaRenderDebug({ component: "VenueDetailPage", venueId: venueId(venue), rawUrl: photo });
  return <Shell title={`${venue.name} — ${venue.venueTypeName || "Venue"}`} description={venue.shortDescription || venue.description}><DetailLink to="/venues" className="inline-flex items-center gap-1 text-sm text-primary underline"><ChevronLeft className="h-4 w-4" />Back to {managed ? "manage venues" : "venues"}</DetailLink><article className="mx-auto mt-6 max-w-5xl"><div className="overflow-hidden border border-border bg-background">{photo ? <button type="button" onClick={() => setLightboxIndex(heroLightboxIndex)} className="block w-full cursor-zoom-in"><img src={photo} alt="" className="h-72 w-full object-cover sm:h-[28rem]" onError={handleImageError} /></button> : <div className="flex h-64 items-end bg-secondary/60 p-7 font-display text-4xl text-muted-foreground">{venue.name}</div>}<div className="grid gap-8 p-6 lg:grid-cols-[minmax(0,1fr)_18rem]"><div><div className="flex flex-wrap items-start gap-3"><h1 className="font-display text-4xl font-bold sm:text-5xl">{venue.name}</h1>{verified && <span className="inline-flex items-center gap-1 border border-primary/40 px-2 py-1 text-xs font-semibold uppercase tracking-wide text-primary"><Check className="h-3.5 w-3.5" />Verified</span>}{venue.sponsored && <span className="border border-primary/40 px-2 py-1 text-xs font-semibold uppercase tracking-wide text-primary">Sponsored</span>}</div><p className="mt-3 flex items-center gap-1 text-muted-foreground"><MapPin className="h-4 w-4" />{publicLocation(venue)}</p><p className="mt-5 text-lg">{venue.venueTypeName || humanize(venue.venueType || "Venue")} · {capacityLabel(venue)}</p><p className="mt-5 text-xl font-semibold text-primary">{priceLabel(venue)}</p></div><aside className="border border-border bg-secondary/20 p-4"><button type="button" onClick={request} className="min-h-12 w-full bg-primary px-4 text-sm font-medium text-primary-foreground">Request venue</button><button type="button" onClick={toggleSaved} className="mt-3 flex min-h-11 w-full items-center justify-center gap-2 border border-border px-4 text-sm"><Heart className={`h-4 w-4 ${saved ? "fill-primary text-primary" : ""}`} />{saved ? "Saved" : "Save venue"}</button>{venue.contactEmail && <a href={`mailto:${venue.contactEmail}`} className="mt-3 flex min-h-11 items-center justify-center border border-border px-4 text-sm">Message venue</a>}{saveError && <p role="alert" className="mt-3 text-sm text-destructive">{saveError}</p>}</aside></div></div>
    {galleryImages.length > 1 && <section className="mt-10"><h2 className="font-display text-3xl font-semibold">Gallery</h2><div className="mt-5 grid gap-3 sm:grid-cols-3">{galleryImages.slice(0, 20).map((item, index) => <button key={index} type="button" onClick={() => setLightboxIndex(index + galleryOffset)} className="aspect-[4/3] cursor-zoom-in overflow-hidden"><img src={item.src} alt={item.caption || ""} className="h-full w-full object-cover transition-transform hover:scale-105" onError={handleImageError} /></button>)}</div></section>}
    <section className="mt-10 grid gap-10 border-t border-border pt-8 lg:grid-cols-2"><div><h2 className="font-display text-3xl font-semibold">About this venue</h2><p className="mt-4 whitespace-pre-wrap leading-relaxed text-muted-foreground">{venue.description || venue.shortDescription || "More details will be shared by the venue."}</p>{venue.suitableEventTypes?.length > 0 && <><h3 className="mt-8 font-display text-2xl font-semibold">Suitable for</h3><TagList items={venue.suitableEventTypes} /></>}</div><div><h2 className="font-display text-3xl font-semibold">Capacity</h2><Capacity venue={venue} /><h3 className="mt-8 font-display text-2xl font-semibold">Amenities</h3><TagList items={venue.amenities} empty="Amenities are shared on request." /></div></section>
    <section className="mt-10 grid gap-10 border-t border-border pt-8 lg:grid-cols-2"><div><h2 className="font-display text-3xl font-semibold">Pricing</h2><p className="mt-4 text-lg font-medium text-primary">{priceLabel(venue)}</p>{venue.pricing?.description || venue.pricingDescription ? <p className="mt-3 whitespace-pre-wrap text-muted-foreground">{venue.pricing?.description || venue.pricingDescription}</p> : null}{venue.minimumBookingHours ? <p className="mt-3 text-sm text-muted-foreground">Minimum booking: {venue.minimumBookingHours} hours</p> : null}</div><div><h2 className="font-display text-3xl font-semibold">Location</h2><p className="mt-4 text-muted-foreground">{publicLocation(venue)}</p><MapLocation location={venue.location || venue} label={venue.name} hidden={["private", "private_until_booking"].includes(venue.locationVisibility)} /></div></section>
    {(venue.houseRulesText || venue.rules?.length) && <section className="mt-10 border-t border-border pt-8"><h2 className="font-display text-3xl font-semibold">Venue rules</h2>{venue.rules?.length ? <TagList items={venue.rules} /> : null}{venue.houseRulesText && <p className="mt-4 whitespace-pre-wrap text-muted-foreground">{venue.houseRulesText}</p>}</section>}
    <section className="mt-10 flex flex-wrap justify-between gap-4 border-t border-border pt-8">{venueId(venue) != null && <Link to={`/report?entityType=venue&entityId=${encodeURIComponent(venueId(venue))}&contentUrl=${encodeURIComponent(window.location.href)}`} className="text-sm text-muted-foreground underline">Report venue</Link>}{venue.organization?.name && <p className="text-sm text-muted-foreground">Listed by {venue.organization.name}</p>}</section>
    {state.similar.length > 0 && <section className="mt-10 border-t border-border pt-8"><h2 className="font-display text-3xl font-semibold">Similar venues</h2><div className="mt-5 grid gap-5 md:grid-cols-3">{state.similar.map((item) => <VenueCard key={item.id} venue={item} compact />)}</div></section>}
  </article>{inquiryOpen && <InquiryForm venue={venue} onClose={() => setInquiryOpen(false)} />}{lightboxIndex != null && <ImageLightbox images={lightboxImages} index={lightboxIndex} onClose={() => setLightboxIndex(null)} onNavigate={setLightboxIndex} onImageError={handleImageError} />}<div className="fixed inset-x-0 bottom-0 z-40 border-t border-border bg-background/95 p-3 backdrop-blur lg:hidden"><div className="mx-auto flex max-w-xl items-center justify-between gap-3"><span className="text-sm font-medium text-primary">{priceLabel(venue)}</span><button type="button" onClick={request} className="bg-primary px-4 py-3 text-sm text-primary-foreground">Request venue</button></div></div></Shell>;
}

function TagList({ items = [], empty }) { return items.length ? <div className="mt-4 flex flex-wrap gap-2">{items.map((item, index) => <span key={item.slug || item.id || index} className="border border-border bg-secondary/20 px-3 py-1.5 text-sm">{item.name || humanize(item.slug || item)}</span>)}</div> : <p className="mt-4 text-sm text-muted-foreground">{empty}</p>; }
function Capacity({ venue }) { const c = venue.capacity || {}; const fields = [["Maximum", c.max ?? venue.capacityMax], ["Standing", c.standing ?? venue.standingCapacity], ["Seated", c.seated ?? venue.seatedCapacity], ["Dinner", c.dining ?? venue.diningCapacity], ["Classroom", c.classroom ?? venue.classroomCapacity], ["Size", (c.sizeSqm ?? venue.sizeSqm) && `${c.sizeSqm ?? venue.sizeSqm} m²`]].filter(([, value]) => value); return fields.length ? <dl className="mt-4 grid grid-cols-2 gap-3">{fields.map(([label, value]) => <div key={label} className="border border-border p-3"><dt className="text-xs uppercase tracking-wide text-muted-foreground">{label}</dt><dd className="mt-1 font-semibold">{value}{label !== "Size" ? " guests" : ""}</dd></div>)}</dl> : <p className="mt-4 text-muted-foreground">Capacity is available on request.</p>; }

const emptyVenue = { name: "", shortDescription: "", description: "", venueType: "", addressLine1: "", addressLine2: "", postalCode: "", city: "", municipality: "", region: "", country: "Sweden", countryCode: "SE", googlePlaceId: "", formattedAddress: "", latitude: "", longitude: "", locationVisibility: "exact", capacityMin: "", capacityMax: "", standingCapacity: "", seatedCapacity: "", diningCapacity: "", classroomCapacity: "", sizeSqm: "", priceFrom: "", priceUnit: "contact", currency: "SEK", pricingDescription: "", minimumBookingHours: "", availabilityType: "calendar", availability: [], houseRulesText: "", amenities: [], suitableEventTypes: [], organizationId: "" };
