function toForm(venue) { const location = venue.location || {}; const pricing = venue.pricing || {}; const capacity = venue.capacity || {}; return { ...emptyVenue, ...venue, addressLine1: venue.addressLine1 || location.addressLine1 || venue.address || "", addressLine2: venue.addressLine2 || location.addressLine2 || "", postalCode: venue.postalCode || location.postalCode || "", city: venue.city || location.locality || "", municipality: venue.municipality || location.municipality || "", region: venue.region || location.region || "", country: venue.country || location.country || "Sweden", countryCode: venue.countryCode || location.countryCode || "", googlePlaceId: venue.googlePlaceId || location.googlePlaceId || "", formattedAddress: venue.formattedAddress || location.formattedAddress || "", latitude: venue.latitude ?? location.latitude ?? "", longitude: venue.longitude ?? location.longitude ?? "", capacityMin: venue.capacityMin ?? capacity.min ?? "", capacityMax: venue.capacityMax ?? capacity.max ?? "", standingCapacity: venue.standingCapacity ?? capacity.standing ?? "", seatedCapacity: venue.seatedCapacity ?? capacity.seated ?? "", diningCapacity: venue.diningCapacity ?? capacity.dining ?? "", classroomCapacity: venue.classroomCapacity ?? capacity.classroom ?? "", sizeSqm: venue.sizeSqm ?? capacity.sizeSqm ?? "", priceFrom: venue.priceFrom ?? pricing.from ?? "", priceUnit: venue.priceUnit || pricing.unit || "contact", currency: venue.currency || pricing.currency || "SEK", pricingDescription: venue.pricingDescription || pricing.description || "", amenities: (venue.amenities || []).map((item) => item.slug || item), suitableEventTypes: (venue.suitableEventTypes || []).map((item) => item.slug || item), organizationId: venue.organizationId || venue.organization?.id || "" }; }

export function VenueEditorPage() {
  const { id } = useParams(); const editing = Boolean(id); const navigate = useNavigate(); const taxonomy = useTaxonomy(); const isAdministrator = JSON.parse(localStorage.getItem("authUser") || "null")?.role === "admin"; const [form, setForm] = useState(emptyVenue); const [organization, setOrganization] = useState({ name: "", description: "", websiteUrl: "", phone: "", contactEmail: "" }); const [pendingCover, setPendingCover] = useState(null); const [pendingGallery, setPendingGallery] = useState([]); const [state, setState] = useState({ loading: editing, saving: false, error: "" });
  useEffect(() => { if (!editing) return; apiFetch(`/api/venues/${id}`, { headers: authHeaders() }).then(async (response) => { const data = await response.json(); if (!response.ok) throw new Error(getError(data, "Unable to load venue.")); const venue = data.venue || data; setForm(toForm(venue)); setOrganization({ name: venue.organization?.name || "", description: venue.organization?.description || "", websiteUrl: venue.organization?.websiteUrl || "", phone: venue.organization?.phone || "", contactEmail: venue.organization?.contactEmail || "" }); }).catch((error) => setState((current) => ({ ...current, error: error.message }))).finally(() => setState((current) => ({ ...current, loading: false }))); }, [editing, id]);
  const update = (key) => (event) => setForm((current) => ({ ...current, [key]: event.target.value })); const toggle = (key, value) => setForm((current) => ({ ...current, [key]: current[key].includes(value) ? current[key].filter((item) => item !== value) : [...current[key], value] })); const applyPlace = (place) => setForm((current) => ({ ...current, ...place, city: place.locality || current.city }));
  useEffect(() => { const receivePlace = (event) => applyPlace(event.detail); const receiveCover = (event) => setPendingCover(event.detail); const receiveGallery = (event) => setPendingGallery(event.detail); window.addEventListener("ykcircle:venue-place-selected", receivePlace); window.addEventListener("ykcircle:venue-cover-selected", receiveCover); window.addEventListener("ykcircle:venue-gallery-selected", receiveGallery); return () => { window.removeEventListener("ykcircle:venue-place-selected", receivePlace); window.removeEventListener("ykcircle:venue-cover-selected", receiveCover); window.removeEventListener("ykcircle:venue-gallery-selected", receiveGallery); }; }, []);
  const applyTestPreset = (event) => { const presetIndex = Number(event.target.value); const preset = testVenuePresets[presetIndex]; if (!Number.isInteger(presetIndex) || !preset) return; const [organizationName, values] = preset; const types = taxonomy.value.venueTypes; const eventTypes = taxonomy.value.eventTypes; const amenities = taxonomy.value.amenities; setOrganization({ name: organizationName, description: "Demo organization created for marketplace testing.", websiteUrl: "", phone: "", contactEmail: "" }); setForm({ ...emptyVenue, ...values, availability: demoWeeklyAvailability, organizationId: "", venueType: types.length ? types[presetIndex % types.length].slug : "", suitableEventTypes: eventTypes.slice(presetIndex % Math.max(eventTypes.length, 1), (presetIndex % Math.max(eventTypes.length, 1)) + 3).map((item) => item.slug), amenities: amenities.slice(presetIndex % Math.max(amenities.length, 1), (presetIndex % Math.max(amenities.length, 1)) + 5).map((item) => item.slug) }); };
  const save = async (event) => { event.preventDefault(); setState((current) => ({ ...current, saving: true, error: "" })); try { if (!form.availability.length) throw new Error("Add at least one weekly availability period."); if (!editing && !pendingCover) throw new Error("Choose a cover image for the venue."); let organizationId = form.organizationId; if (!organizationId) { if (!organization.name.trim()) throw new Error("Enter the organization that owns this venue."); const response = await apiFetch("/api/organizations", { method: "POST", headers: { ...authHeaders(), "Content-Type": "application/json" }, body: JSON.stringify(organization) }); const data = await response.json(); if (!response.ok) throw new Error(getError(data, "Unable to create organization.")); organizationId = (data.organization || data).id; }
    const payload = { organizationId, name: form.name, shortDescription: form.shortDescription, description: form.description, venueType: form.venueType, addressLine1: form.addressLine1, addressLine2: form.addressLine2, postalCode: form.postalCode, city: form.city, municipality: form.municipality, region: form.region, country: form.country, countryCode: form.countryCode, googlePlaceId: form.googlePlaceId, formattedAddress: form.formattedAddress, latitude: toNumber(form.latitude), longitude: toNumber(form.longitude), locationVisibility: form.locationVisibility, capacityMin: toNumber(form.capacityMin), capacityMax: toNumber(form.capacityMax), standingCapacity: toNumber(form.standingCapacity), seatedCapacity: toNumber(form.seatedCapacity), diningCapacity: toNumber(form.diningCapacity), classroomCapacity: toNumber(form.classroomCapacity), sizeSqm: toNumber(form.sizeSqm), priceFrom: toNumber(form.priceFrom), priceUnit: form.priceUnit, currency: form.currency, pricingDescription: form.pricingDescription, minimumBookingHours: toNumber(form.minimumBookingHours), availabilityType: form.availabilityType, availability: form.availability, houseRulesText: form.houseRulesText, amenities: form.amenities, suitableEventTypes: form.suitableEventTypes };
    const response = await apiFetch(editing ? `/api/venues/${id}` : "/api/venues", { method: editing ? "PATCH" : "POST", headers: { ...authHeaders(), "Content-Type": "application/json" }, body: JSON.stringify(payload) }); const data = await response.json(); if (!response.ok) throw new Error(getError(data, "Unable to save venue."));
    const savedVenue = data.venue || data;
    const upload = async (file, kind) => { const body = new FormData(); body.append("image", file); body.append("kind", kind); body.append("altText", `${form.name || "Venue"} ${kind === "cover" ? "cover" : "gallery image"}`); const imageResponse = await apiFetch(`/api/venues/${savedVenue.id}/media`, { method: "POST", headers: authHeaders(), body }); const imageData = await imageResponse.json(); if (!imageResponse.ok) throw new Error(getError(imageData, "Unable to upload venue image.")); };
    if (pendingCover) await upload(pendingCover, "cover");
    for (const image of pendingGallery) await upload(image, "gallery");
    navigate("/profile/venues");
  } catch (error) { setState((current) => ({ ...current, error: error.message })); } finally { setState((current) => ({ ...current, saving: false })); } };
  if (state.loading) return <Shell title="Venue editor" noindex><div className="max-w-3xl"><Skeleton className="h-11 w-2/5" /><Skeleton className="mt-8 h-96 w-full" /></div></Shell>;
  return <Shell title={editing ? "Edit venue" : "List a venue"} noindex><Link to="/profile/venues" className="text-sm text-primary underline">Back to my venues</Link><h1 className="mt-5 font-display text-4xl font-bold">{editing ? "Edit venue" : "List a venue"}</h1><p className="mt-3 max-w-2xl text-muted-foreground">{editing ? "Changes to public listings are reviewed by YKCircle." : "Your organization owns this venue. New listings start as drafts until they are approved."}</p><form onSubmit={save} className="mt-8 max-w-4xl space-y-9">{!editing && isAdministrator && <label className="block border border-primary/30 bg-primary/5 p-4 text-sm">Testing preset<select defaultValue="" onChange={applyTestPreset} className={inputClass}><option value="" disabled>Choose one of 10 sample venues</option>{testVenuePresets.map(([, values], index) => <option key={values.name} value={index}>{index + 1}. {values.name}</option>)}</select><span className="mt-1 block text-xs text-muted-foreground">Populates the organization and all venue fields. Images can be added through the media flow after creation.</span></label>}<EditorSection title="Organization">{editing && form.organizationId ? <p className="text-sm text-muted-foreground">This listing belongs to {organization.name || "your organization"}.</p> : <><Input label="Organization name" required value={organization.name} onChange={(event) => setOrganization((current) => ({ ...current, name: event.target.value }))} /><Input label="Organization website" type="url" value={organization.websiteUrl} onChange={(event) => setOrganization((current) => ({ ...current, websiteUrl: event.target.value }))} /><Input label="Organization contact email" type="email" value={organization.contactEmail} onChange={(event) => setOrganization((current) => ({ ...current, contactEmail: event.target.value }))} /></>}</EditorSection><EditorSection title="Venue details"><Input label="Venue name" required value={form.name} onChange={update("name")} /><FilterSelect label="Venue type" value={form.venueType} onChange={(value) => setForm((current) => ({ ...current, venueType: value }))} options={taxonomy.value.venueTypes} placeholder="Choose a venue type" /><label className="sm:col-span-2 text-sm font-medium">Short description<textarea value={form.shortDescription} onChange={update("shortDescription")} className={textareaClass} /></label><label className="sm:col-span-2 text-sm font-medium">About this venue<textarea value={form.description} onChange={update("description")} className={textareaClass} /></label></EditorSection><EditorSection title="Location"><Input label="Address" value={form.addressLine1} onChange={update("addressLine1")} /><Input label="Address line 2" value={form.addressLine2} onChange={update("addressLine2")} /><Input label="Postal code" value={form.postalCode} onChange={update("postalCode")} /><Input label="City / locality" required value={form.city} onChange={update("city")} /><Input label="Municipality" value={form.municipality} onChange={update("municipality")} /><Input label="Region" value={form.region} onChange={update("region")} /><Input label="Country" required value={form.country} onChange={update("country")} /><FilterSelect label="Location privacy" value={form.locationVisibility} onChange={(value) => setForm((current) => ({ ...current, locationVisibility: value }))} options={["exact", "approximate", "private_until_booking"]} placeholder="Choose visibility" /><Input label="Latitude" type="number" value={form.latitude} onChange={update("latitude")} /><Input label="Longitude" type="number" value={form.longitude} onChange={update("longitude")} /></EditorSection><EditorSection title="Capacity"><Input label="Minimum guests" type="number" value={form.capacityMin} onChange={update("capacityMin")} /><Input label="Maximum guests" type="number" value={form.capacityMax} onChange={update("capacityMax")} /><Input label="Standing capacity" type="number" value={form.standingCapacity} onChange={update("standingCapacity")} /><Input label="Seated capacity" type="number" value={form.seatedCapacity} onChange={update("seatedCapacity")} /><Input label="Dinner capacity" type="number" value={form.diningCapacity} onChange={update("diningCapacity")} /><Input label="Classroom capacity" type="number" value={form.classroomCapacity} onChange={update("classroomCapacity")} /><Input label="Size (m²)" type="number" value={form.sizeSqm} onChange={update("sizeSqm")} /></EditorSection><EditorSection title="Pricing and availability"><Input label="Starting price" type="number" value={form.priceFrom} onChange={update("priceFrom")} /><FilterSelect label="Price unit" value={form.priceUnit} onChange={(value) => setForm((current) => ({ ...current, priceUnit: value }))} options={["hour", "half_day", "day", "evening", "person", "event", "contact"]} placeholder="Choose price unit" /><Input label="Currency" value={form.currency} onChange={update("currency")} /><FilterSelect label="Availability" value={form.availabilityType} onChange={(value) => setForm((current) => ({ ...current, availabilityType: value }))} options={["contact", "calendar", "always_open"]} placeholder="Choose availability" /><label className="sm:col-span-2 text-sm font-medium">Pricing description<textarea value={form.pricingDescription} onChange={update("pricingDescription")} className={textareaClass} /></label><Input label="Minimum booking hours" type="number" value={form.minimumBookingHours} onChange={update("minimumBookingHours")} /></EditorSection><EditorSection title="Weekly availability"><VenueScheduleEditor slots={form.availability} onChange={(availability) => setForm((current) => ({ ...current, availability }))} /></EditorSection><EditorSection title="Suitable for">{taxonomy.value.eventTypes.map((item) => <CheckOption key={item.slug} item={item} checked={form.suitableEventTypes.includes(item.slug)} onChange={() => toggle("suitableEventTypes", item.slug)} />)}</EditorSection><EditorSection title="Amenities">{taxonomy.value.amenities.map((item) => <CheckOption key={item.slug} item={item} checked={form.amenities.includes(item.slug)} onChange={() => toggle("amenities", item.slug)} />)}</EditorSection><EditorSection title="Venue rules"><label className="sm:col-span-2 text-sm font-medium">House rules<textarea value={form.houseRulesText} onChange={update("houseRulesText")} placeholder="For example: external catering allowed; music until 22:30; no smoking." className={textareaClass} /></label></EditorSection><button disabled={state.saving} className="bg-primary px-6 py-3 text-sm font-medium text-primary-foreground disabled:opacity-60">{state.saving ? "Saving…" : editing ? "Save changes" : "Create venue draft"}</button></form>{state.error && <p role="alert" className="fixed bottom-6 left-5 z-50 max-w-md border border-destructive/30 bg-background px-4 py-3 text-sm text-destructive shadow-lg sm:left-auto sm:right-6">{state.error}</p>}</Shell>;
}

function EditorSection({ title, children }) { return <section className="border-t border-border pt-7"><h2 className="font-display text-2xl font-semibold">{title}</h2>{title === "Location" && <div className="mt-5"><GoogleLocationPicker onSelect={(place) => window.dispatchEvent(new CustomEvent("ykcircle:venue-place-selected", { detail: place }))} /></div>}<div className="mt-5 grid gap-5 sm:grid-cols-2">{children}</div></section>; }
function VenueScheduleEditor({ slots = [], onChange }) {
  const weekdays = [[1, "Mon"], [2, "Tue"], [3, "Wed"], [4, "Thu"], [5, "Fri"], [6, "Sat"], [0, "Sun"]];
  const hours = Array.from({ length: 14 }, (_, index) => index + 7);
  const [weekStart, setWeekStart] = useState(() => { const today = new Date(); const monday = new Date(today); monday.setDate(today.getDate() - ((today.getDay() + 6) % 7)); monday.setHours(0, 0, 0, 0); return monday; });
  const [selected, setSelected] = useState(null);
  const formatTime = (hour) => `${String(hour).padStart(2, "0")}:00`;
  const timeToMinutes = (value) => { const [hoursValue, minutes = 0] = String(value || "00:00").split(":").map(Number); return hoursValue * 60 + minutes; };
  const displayedWeekdays = weekdays.slice(0, 5);
  const hourHeight = 72;
  const gridHeight = hours.length * hourHeight;
  const removeInterval = (index) => onChange(slots.filter((_, slotIndex) => slotIndex !== index));
  const selectCell = (weekday, hour) => {
    const matchingIndex = slots.findIndex((slot) => Number(slot.weekday) === weekday && timeToMinutes(slot.startTime) < (hour + 1) * 60 && timeToMinutes(slot.endTime) > hour * 60);
    if (matchingIndex >= 0) { setSelected({ index: matchingIndex, ...slots[matchingIndex] }); return; }
    const interval = { weekday, startTime: formatTime(hour), endTime: formatTime(hour + 1) };
    onChange([...slots, interval]); setSelected({ index: slots.length, ...interval });
  };
  const updateSelected = (key, value) => {
    if (!selected) return;
    const next = { ...selected, [key]: key === "weekday" ? Number(value) : value };
    setSelected(next); onChange(slots.map((slot, index) => index === selected.index ? { weekday: next.weekday, startTime: next.startTime, endTime: next.endTime } : slot));
  };
  const today = new Date();
  return <div className="sm:col-span-2">
    <div className="flex flex-wrap items-start justify-between gap-4">
      <div><p className="text-sm text-muted-foreground">Set regular hours on a work-week timeline. Click an empty hour to add availability, or select a block to edit its start and end time.</p><p className="mt-2 text-xs text-muted-foreground">Your browser timezone: {Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC"}. These hours repeat weekly.</p></div>
      <button type="button" onClick={() => setWeekStart(new Date(today.getFullYear(), today.getMonth(), today.getDate() - ((today.getDay() + 6) % 7)))} className="border border-border px-3 py-2 text-sm">Today</button>
    </div>
    <div className="mt-5 flex items-center gap-2"><button type="button" aria-label="Previous week" onClick={() => setWeekStart((current) => new Date(current.getFullYear(), current.getMonth(), current.getDate() - 7))} className="min-h-10 border border-border px-3">‹</button><p className="min-w-52 text-sm font-medium">Work week of {weekStart.toLocaleDateString(undefined, { month: "short", day: "numeric" })}</p><button type="button" aria-label="Next week" onClick={() => setWeekStart((current) => new Date(current.getFullYear(), current.getMonth(), current.getDate() + 7))} className="min-h-10 border border-border px-3">›</button></div>
    <div className="mt-3 overflow-x-auto"><div className="min-w-[720px]"><div className="grid border-l border-t border-border" style={{ gridTemplateColumns: "4.5rem repeat(5, minmax(9rem, 1fr))" }}><div className="border-b border-r border-border bg-secondary/30" />{displayedWeekdays.map(([weekday, label], index) => { const calendarDate = new Date(weekStart); calendarDate.setDate(weekStart.getDate() + index); return <div key={weekday} className="border-b border-r border-border bg-secondary/30 px-3 py-3 text-left text-sm"><strong className="block">{label}</strong><span className="text-muted-foreground">{calendarDate.getDate()}</span></div>; })}</div><div className="grid border-l border-border" style={{ gridTemplateColumns: "4.5rem repeat(5, minmax(9rem, 1fr))" }}><div className="relative border-r border-border" style={{ height: gridHeight }}>{hours.map((hour) => <span key={hour} className="absolute right-2 -translate-y-2 text-xs text-muted-foreground" style={{ top: (hour - 7) * hourHeight }}>{formatTime(hour)}</span>)}</div>{displayedWeekdays.map(([weekday]) => <div key={weekday} className="relative border-r border-border" style={{ height: gridHeight }}>{hours.map((hour) => <button key={hour} type="button" onClick={() => selectCell(weekday, hour)} aria-label={`Add availability on ${weekdays.find(([day]) => day === weekday)?.[1]} at ${formatTime(hour)}`} className="absolute left-0 right-0 border-b border-border/80 hover:bg-secondary/40" style={{ top: (hour - 7) * hourHeight, height: hourHeight }} />)}{hours.slice(0, -1).map((hour) => <span key={`half-${hour}`} className="pointer-events-none absolute left-0 right-0 border-b border-dashed border-border/50" style={{ top: (hour - 6.5) * hourHeight }} />)}{slots.map((slot, index) => { if (Number(slot.weekday) !== weekday) return null; const top = Math.max(0, ((timeToMinutes(slot.startTime) / 60) - 7) * hourHeight); const bottom = Math.min(gridHeight, ((timeToMinutes(slot.endTime) / 60) - 7) * hourHeight); if (bottom <= top) return null; return <button type="button" key={`${weekday}-${index}`} onClick={(event) => { event.stopPropagation(); setSelected({ index, ...slot }); }} className="absolute left-1 right-1 z-10 border border-accent/50 bg-accent/10 p-2 text-left text-xs shadow-sm hover:bg-accent/20" style={{ top: top + 2, height: Math.max(24, bottom - top - 4) }}><strong className="block">Available</strong>{slot.startTime}–{slot.endTime}</button>; })}</div>)}</div></div></div>
    <div className="mt-4 flex flex-wrap gap-2 text-xs"><span className="border border-accent/50 bg-accent/10 px-2 py-1">Available every week</span><span className="px-2 py-1 text-muted-foreground">Click an empty time to add availability</span></div>
    {selected && <div className="mt-5 border border-primary/30 bg-primary/5 p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="font-display text-xl font-semibold">Edit availability</h3><p className="mt-1 text-sm text-muted-foreground">This applies every {weekdays.find(([weekday]) => weekday === Number(selected.weekday))?.[1] || "week"}.</p></div><button type="button" onClick={() => { removeInterval(selected.index); setSelected(null); }} className="text-sm text-destructive">Remove block</button></div><div className="mt-4 grid gap-3 sm:grid-cols-3"><label className="text-sm font-medium">Day<select value={selected.weekday} onChange={(event) => updateSelected("weekday", event.target.value)} className={inputClass}>{weekdays.map(([weekday, label]) => <option key={weekday} value={weekday}>{label}</option>)}</select></label><label className="text-sm font-medium">Start<input type="time" value={selected.startTime} onChange={(event) => updateSelected("startTime", event.target.value)} className={inputClass} /></label><label className="text-sm font-medium">End<input type="time" value={selected.endTime} onChange={(event) => updateSelected("endTime", event.target.value)} className={inputClass} /></label></div></div>}
    <div className="mt-5"><h3 className="font-display text-xl font-semibold">Regular availability</h3>{slots.length ? <div className="mt-3 flex flex-wrap gap-2">{slots.map((slot, index) => <button key={`${slot.weekday}-${slot.startTime}-${index}`} type="button" onClick={() => setSelected({ index, ...slot })} className="border border-border bg-background px-3 py-2 text-sm hover:border-primary">{weekdays.find(([weekday]) => weekday === Number(slot.weekday))?.[1]} · {slot.startTime}–{slot.endTime}</button>)}</div> : <p className="mt-2 text-sm text-muted-foreground">No regular availability selected yet.</p>}</div>
    <div className="mt-7 border-t border-border pt-5"><h3 className="font-display text-xl font-semibold">Venue photos</h3><p className="mt-1 text-sm text-muted-foreground">A cover photo is required. Add optional gallery photos for the venue details page.</p><label className="mt-4 block text-sm font-medium">Cover image<input required type="file" accept="image/jpeg,image/png,image/webp" onChange={(event) => window.dispatchEvent(new CustomEvent("ykcircle:venue-cover-selected", { detail: event.target.files?.[0] || null }))} className={inputClass} /></label><label className="mt-4 block text-sm font-medium">Gallery images<input type="file" accept="image/jpeg,image/png,image/webp" multiple onChange={(event) => window.dispatchEvent(new CustomEvent("ykcircle:venue-gallery-selected", { detail: Array.from(event.target.files || []) }))} className={inputClass} /></label></div>
  </div>;
}

function LegacyVenueScheduleEditor({ slots = [], onChange }) {
  const days = [[1, "Monday"], [2, "Tuesday"], [3, "Wednesday"], [4, "Thursday"], [5, "Friday"], [6, "Saturday"], [0, "Sunday"]];
  const changeDay = (weekday, values) => onChange([...slots.filter((slot) => slot.weekday !== weekday), ...values]);
  return <div className="sm:col-span-2"><p className="text-sm text-muted-foreground">Choose the recurring hours when this venue can host YKCircle events. Event creators see only the hours for their selected date.</p><div className="mt-4 space-y-3">{days.map(([weekday, label]) => { const slot = slots.find((item) => Number(item.weekday) === weekday); return <div key={weekday} className="grid items-center gap-3 border border-border p-3 sm:grid-cols-[9rem_1fr_1fr]"><label className="flex items-center gap-2 text-sm font-medium"><input type="checkbox" checked={Boolean(slot)} onChange={(event) => changeDay(weekday, event.target.checked ? [{ weekday, startTime: "09:00", endTime: "17:00" }] : [])} />{label}</label><input aria-label={`${label} start time`} type="time" disabled={!slot} value={slot?.startTime || "09:00"} onChange={(event) => changeDay(weekday, [{ ...(slot || { weekday, endTime: "17:00" }), startTime: event.target.value }])} className={inputClass} /><input aria-label={`${label} end time`} type="time" disabled={!slot} value={slot?.endTime || "17:00"} onChange={(event) => changeDay(weekday, [{ ...(slot || { weekday, startTime: "09:00" }), endTime: event.target.value }])} className={inputClass} /></div>; })}</div><div className="mt-7 border-t border-border pt-5"><h3 className="font-display text-xl font-semibold">Venue photos</h3><p className="mt-1 text-sm text-muted-foreground">A cover photo is required. Add optional gallery photos for the venue details page.</p><label className="mt-4 block text-sm font-medium">Cover image<input required type="file" accept="image/jpeg,image/png,image/webp" onChange={(event) => window.dispatchEvent(new CustomEvent("ykcircle:venue-cover-selected", { detail: event.target.files?.[0] || null }))} className={inputClass} /></label><label className="mt-4 block text-sm font-medium">Gallery images<input type="file" accept="image/jpeg,image/png,image/webp" multiple onChange={(event) => window.dispatchEvent(new CustomEvent("ykcircle:venue-gallery-selected", { detail: Array.from(event.target.files || []) }))} className={inputClass} /></label></div></div>;
}
function Input({ label, required, type = "text", value, onChange }) { if (["Latitude", "Longitude"].includes(label)) return null; return <label className="text-sm font-medium">{label}{required && " *"}<input required={required} type={type} value={value ?? ""} onChange={onChange} className={inputClass} /></label>; }
function CheckOption({ item, checked, onChange }) { return <label className="flex min-h-11 items-center gap-2 border border-border px-3 text-sm"><input type="checkbox" checked={checked} onChange={onChange} />{item.name || humanize(item.slug || item)}</label>; }

export function SavedVenuesPage() {
  const [state, setState] = useState({ loading: true, error: "", venues: [] }); const navigate = useNavigate();
  const load = useCallback(async () => { if (!localStorage.getItem("authToken")) return navigate(`/login?from=${encodeURIComponent("/profile/saved-venues")}`); setState((current) => ({ ...current, loading: true, error: "" })); try { const response = await apiFetch("/api/my/saved-venues", { headers: authHeaders() }); const data = await response.json(); if (!response.ok) throw new Error(getError(data, "Unable to load saved venues.")); setState({ loading: false, error: "", venues: asList(data, "venues").length ? asList(data, "venues") : asList(data, "savedVenues") }); } catch (error) { setState((current) => ({ ...current, loading: false, error: error.message })); } }, [navigate]); useEffect(() => { load(); }, [load]);
  return <Shell title="Saved venues" noindex><h1 className="font-display text-4xl font-bold">My saved venues</h1>{state.error ? <ErrorState error={state.error} retry={load} /> : state.loading ? <div className="mt-8 grid gap-5 md:grid-cols-2 lg:grid-cols-3">{[1, 2, 3].map((item) => <VenueCardSkeleton key={item} />)}</div> : state.venues.length ? <div className="mt-8 grid gap-5 md:grid-cols-2 lg:grid-cols-3">{state.venues.map((item) => <VenueCard key={item.venue?.id || item.id} venue={item.venue || item} />)}</div> : <p className="mt-8 border border-border p-6 text-muted-foreground">You have not saved any venues yet.</p>}</Shell>;
}

export function VenueCityOrDetailPage() {
  const { city } = useParams();
  return /^\d+$/.test(city || "") ? <VenueDetailPage legacyId managed /> : <VenuesDiscoveryPage city={city} />;
}

export function VenueSearchRoutePage() {
  const { city, venueType } = useParams();
  return <VenuesDiscoveryPage city={city} venueType={venueType} />;
}
